import mongoose from 'mongoose'

export const NAME_MAX_LENGTH = 100
export const ACCOUNT_NUMBER_MAX_LENGTH = 64
export const TRANSACTION_STATUSES = ['PENDING', 'PAID', 'FAILED', 'CANCELLED']

// =====> transactionschema defined here
export const transactionSchema = new mongoose.Schema(
  {
    // Unique transaction ID generated by the client
    tranId: {
      type: String,
      required: true,
      immutable: true,
      unique: true,
      index: true,
    },

    // Name of the person making the transaction
    name: {
      type: String,
      required: true,
      trim: true,
      maxlength: NAME_MAX_LENGTH,
    },

    // Account number of the person making the transaction
    accountNumber: {
      type: String,
      required: true,
      trim: true,
      maxlength: ACCOUNT_NUMBER_MAX_LENGTH,
    },

    // Amount of the transaction in whole KHR (Cambodian Riel)
    amount: {
      type: Number,
      required: true,
      validate: {
        validator: (value) => Number.isSafeInteger(value) && value > 0,
        message: 'Amount must be a positive safe integer representing whole KHR.',
      },
    },

    // Currency of the transaction, defaulting to KHR
    currency: {
      type: String,
      enum: ['KHR'],
      default: 'KHR',
    },

    // Status of the transaction, defaulting to PENDING
    status: {
      type: String,
      enum: TRANSACTION_STATUSES,
      default: 'PENDING',
    },

    // Response code from the payment gateway, if applicable
    paywayResponseCode: {
      type: String,
      default: null,
    },

    // Response message from the payment gateway, if applicable
    paidAt: {
      type: Date,
      default: null,
    },
  },
  { timestamps: true },
)

export const Transaction = mongoose.model('Transaction', transactionSchema)

